/bin/bash -c "python3 - <<'PY'
from fractions import Fraction as F
rows=[[F(4,5),F(1,10),F(1,10)], [F(1,5),F(7,10),F(1,10)], [F(1,4),F(1,4),F(1,2)]]
def eta(a,b):
    if b<a:return 1-b/a
    if b>a:return 1-(1-b)/(1-a)
    return F(0)
for y,row in enumerate(rows):
    q=[F(int(j==y)) for j in range(3)]
    print('Row',y,'identity-baseline nuisance',max(eta(a,b) for a,b in zip(q,row)),'error',1-row[y])
PY"
